// Node-RED function node: IDENTIFY MODE
//
// What: inspects the raw MQTT payload and routes it to the correct
//       mode-specific validation branch.
// Why:  this is where Variety becomes visible in the flow. Four structurally
//       different payload shapes arrive on transport/raw/#, and each one is
//       sent down its own branch instead of through one generic handler.
//
// Outputs: 1 bus | 2 tram | 3 train | 4 demand | 5 unroutable
var payload = msg.payload;

// Node-RED may deliver a Buffer or a string if the MQTT node is not set to
// parse JSON. Parsing defensively keeps the flow robust.
if (Buffer.isBuffer(payload)) { payload = payload.toString('utf8'); }
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); }
    catch (e) {
        msg.rejection = { mode: 'unknown', reason: 'payload is not valid JSON' };
        return [null, null, null, null, msg];
    }
}

if (payload === null || typeof payload !== 'object' || Array.isArray(payload)) {
    msg.rejection = { mode: 'unknown', reason: 'payload is not a JSON object' };
    return [null, null, null, null, msg];
}

msg.payload = payload;
msg.receivedAt = new Date().toISOString();

if (payload.eventType === 'locationDemand') {
    msg.transportMode = 'demand';
    return [null, null, null, msg, null];
}

if (payload.eventType === 'telemetry') {
    if (payload.transportMode === 'bus') { msg.transportMode = 'bus'; return [msg, null, null, null, null]; }
    if (payload.transportMode === 'tram') { msg.transportMode = 'tram'; return [null, msg, null, null, null]; }
    if (payload.transportMode === 'train') { msg.transportMode = 'train'; return [null, null, msg, null, null]; }
}

msg.rejection = {
    mode: String(payload.transportMode || 'unknown'),
    reason: 'unrecognised eventType/transportMode combination'
};
return [null, null, null, null, msg];

// Node-RED function node: VALIDATE BUS
//
// Bus-specific rules: health is normal|degraded|breakdown, and modeData must
// carry roadSegmentId and nextStopId. A bus is road-based, so its disruption
// state is a breakdown - it has no track segment and no platform.
//
// Outputs: 1 accepted | 2 rejected
var MAX_OCCUPANCY_RATIO = 1.5;
function isNonEmptyString(v) { return typeof v === 'string' && v.length > 0; }
function isFiniteNumber(v) { return typeof v === 'number' && isFinite(v); }
function isInteger(v) { return isFiniteNumber(v) && Math.floor(v) === v; }

function checkVehicleCommon(p, errors) {
    if (!isNonEmptyString(p.eventId)) errors.push('eventId is required');
    if (!isNonEmptyString(p.vehicleId)) errors.push('vehicleId is required');
    if (!isNonEmptyString(p.routeId)) errors.push('routeId is required');
    if (!isNonEmptyString(p.serviceId)) errors.push('serviceId is required');
    if (!isNonEmptyString(p.timestamp) || isNaN(Date.parse(p.timestamp))) {
        errors.push('timestamp must be a valid ISO-8601 date');
    }
    if (!isFiniteNumber(p.latitude) || p.latitude < -90 || p.latitude > 90) {
        errors.push('latitude must be between -90 and 90');
    }
    if (!isFiniteNumber(p.longitude) || p.longitude < -180 || p.longitude > 180) {
        errors.push('longitude must be between -180 and 180');
    }
    if (!isFiniteNumber(p.speedKph) || p.speedKph < 0) errors.push('speedKph must be >= 0');
    if (!isInteger(p.occupancy) || p.occupancy < 0) errors.push('occupancy must be >= 0');
    if (!isInteger(p.capacity) || p.capacity <= 0) errors.push('capacity must be > 0');
    if (isInteger(p.occupancy) && isInteger(p.capacity) && p.capacity > 0
        && p.occupancy > p.capacity * MAX_OCCUPANCY_RATIO) {
        errors.push('occupancy ' + p.occupancy + ' exceeds ' + MAX_OCCUPANCY_RATIO
            + 'x capacity ' + p.capacity);
    }
    if (!isInteger(p.delaySeconds)) errors.push('delaySeconds must be an integer');
    if (p.modeData === null || typeof p.modeData !== 'object' || Array.isArray(p.modeData)) {
        errors.push('modeData object is required');
    }
}
var p = msg.payload;
var errors = [];

checkVehicleCommon(p, errors);

if (p.transportMode !== 'bus') errors.push('transportMode must be bus');
if (['normal', 'degraded', 'breakdown'].indexOf(p.health) === -1) {
    errors.push("health must be one of normal, degraded, breakdown (got '" + p.health + "')");
}
if (p.modeData && typeof p.modeData === 'object') {
    if (!isNonEmptyString(p.modeData.roadSegmentId)) errors.push('modeData.roadSegmentId is required for a bus');
    if (!isNonEmptyString(p.modeData.nextStopId)) errors.push('modeData.nextStopId is required for a bus');
}
if (p.speedKph > 120) errors.push('speedKph above the plausible bus maximum of 120');

if (errors.length > 0) {
    msg.rejection = { mode: 'bus', reason: errors.join('; '), errors: errors };
    return [null, msg];
}
msg.validatedBy = 'node-red:validate-bus';
return [msg, null];

// Node-RED function node: VALIDATE TRAM
//
// Tram-specific rules: health is normal|degraded|blocked, and modeData must
// carry trackSegmentId, direction and nextStopId. A tram runs on rails, so it
// cannot be diverted - a blockage is a property of a track segment plus a
// direction, which is why those two fields are mandatory here and absent for a bus.
//
// Outputs: 1 accepted | 2 rejected
var MAX_OCCUPANCY_RATIO = 1.5;
function isNonEmptyString(v) { return typeof v === 'string' && v.length > 0; }
function isFiniteNumber(v) { return typeof v === 'number' && isFinite(v); }
function isInteger(v) { return isFiniteNumber(v) && Math.floor(v) === v; }

function checkVehicleCommon(p, errors) {
    if (!isNonEmptyString(p.eventId)) errors.push('eventId is required');
    if (!isNonEmptyString(p.vehicleId)) errors.push('vehicleId is required');
    if (!isNonEmptyString(p.routeId)) errors.push('routeId is required');
    if (!isNonEmptyString(p.serviceId)) errors.push('serviceId is required');
    if (!isNonEmptyString(p.timestamp) || isNaN(Date.parse(p.timestamp))) {
        errors.push('timestamp must be a valid ISO-8601 date');
    }
    if (!isFiniteNumber(p.latitude) || p.latitude < -90 || p.latitude > 90) {
        errors.push('latitude must be between -90 and 90');
    }
    if (!isFiniteNumber(p.longitude) || p.longitude < -180 || p.longitude > 180) {
        errors.push('longitude must be between -180 and 180');
    }
    if (!isFiniteNumber(p.speedKph) || p.speedKph < 0) errors.push('speedKph must be >= 0');
    if (!isInteger(p.occupancy) || p.occupancy < 0) errors.push('occupancy must be >= 0');
    if (!isInteger(p.capacity) || p.capacity <= 0) errors.push('capacity must be > 0');
    if (isInteger(p.occupancy) && isInteger(p.capacity) && p.capacity > 0
        && p.occupancy > p.capacity * MAX_OCCUPANCY_RATIO) {
        errors.push('occupancy ' + p.occupancy + ' exceeds ' + MAX_OCCUPANCY_RATIO
            + 'x capacity ' + p.capacity);
    }
    if (!isInteger(p.delaySeconds)) errors.push('delaySeconds must be an integer');
    if (p.modeData === null || typeof p.modeData !== 'object' || Array.isArray(p.modeData)) {
        errors.push('modeData object is required');
    }
}
var p = msg.payload;
var errors = [];

checkVehicleCommon(p, errors);

if (p.transportMode !== 'tram') errors.push('transportMode must be tram');
if (['normal', 'degraded', 'blocked'].indexOf(p.health) === -1) {
    errors.push("health must be one of normal, degraded, blocked (got '" + p.health + "')");
}
if (p.modeData && typeof p.modeData === 'object') {
    if (!isNonEmptyString(p.modeData.trackSegmentId)) errors.push('modeData.trackSegmentId is required for a tram');
    if (['inbound', 'outbound'].indexOf(p.modeData.direction) === -1) {
        errors.push('modeData.direction must be inbound or outbound');
    }
    if (!isNonEmptyString(p.modeData.nextStopId)) errors.push('modeData.nextStopId is required for a tram');
}
if (p.speedKph > 80) errors.push('speedKph above the plausible tram maximum of 80');

if (errors.length > 0) {
    msg.rejection = { mode: 'tram', reason: errors.join('; '), errors: errors };
    return [null, msg];
}
msg.validatedBy = 'node-red:validate-tram';
return [msg, null];

// Node-RED function node: VALIDATE TRAIN
//
// Train-specific rules: health is normal|degraded|cancelled, and modeData must
// carry stationId, platform, carriageCount and nextStationId. A train stops at
// stations with numbered platforms and has a variable carriage count, which is
// what determines its capacity - none of these concepts exist for a bus.
//
// Outputs: 1 accepted | 2 rejected
var MAX_OCCUPANCY_RATIO = 1.5;
function isNonEmptyString(v) { return typeof v === 'string' && v.length > 0; }
function isFiniteNumber(v) { return typeof v === 'number' && isFinite(v); }
function isInteger(v) { return isFiniteNumber(v) && Math.floor(v) === v; }

function checkVehicleCommon(p, errors) {
    if (!isNonEmptyString(p.eventId)) errors.push('eventId is required');
    if (!isNonEmptyString(p.vehicleId)) errors.push('vehicleId is required');
    if (!isNonEmptyString(p.routeId)) errors.push('routeId is required');
    if (!isNonEmptyString(p.serviceId)) errors.push('serviceId is required');
    if (!isNonEmptyString(p.timestamp) || isNaN(Date.parse(p.timestamp))) {
        errors.push('timestamp must be a valid ISO-8601 date');
    }
    if (!isFiniteNumber(p.latitude) || p.latitude < -90 || p.latitude > 90) {
        errors.push('latitude must be between -90 and 90');
    }
    if (!isFiniteNumber(p.longitude) || p.longitude < -180 || p.longitude > 180) {
        errors.push('longitude must be between -180 and 180');
    }
    if (!isFiniteNumber(p.speedKph) || p.speedKph < 0) errors.push('speedKph must be >= 0');
    if (!isInteger(p.occupancy) || p.occupancy < 0) errors.push('occupancy must be >= 0');
    if (!isInteger(p.capacity) || p.capacity <= 0) errors.push('capacity must be > 0');
    if (isInteger(p.occupancy) && isInteger(p.capacity) && p.capacity > 0
        && p.occupancy > p.capacity * MAX_OCCUPANCY_RATIO) {
        errors.push('occupancy ' + p.occupancy + ' exceeds ' + MAX_OCCUPANCY_RATIO
            + 'x capacity ' + p.capacity);
    }
    if (!isInteger(p.delaySeconds)) errors.push('delaySeconds must be an integer');
    if (p.modeData === null || typeof p.modeData !== 'object' || Array.isArray(p.modeData)) {
        errors.push('modeData object is required');
    }
}
var p = msg.payload;
var errors = [];

checkVehicleCommon(p, errors);

if (p.transportMode !== 'train') errors.push('transportMode must be train');
if (['normal', 'degraded', 'cancelled'].indexOf(p.health) === -1) {
    errors.push("health must be one of normal, degraded, cancelled (got '" + p.health + "')");
}
if (p.modeData && typeof p.modeData === 'object') {
    if (!isNonEmptyString(p.modeData.stationId)) errors.push('modeData.stationId is required for a train');
    if (!isInteger(p.modeData.platform) || p.modeData.platform < 1 || p.modeData.platform > 20) {
        errors.push('modeData.platform must be an integer between 1 and 20');
    }
    if (!isInteger(p.modeData.carriageCount) || p.modeData.carriageCount < 1 || p.modeData.carriageCount > 12) {
        errors.push('modeData.carriageCount must be an integer between 1 and 12');
    }
    if (!isNonEmptyString(p.modeData.nextStationId)) errors.push('modeData.nextStationId is required for a train');
}
if (p.speedKph > 160) errors.push('speedKph above the plausible train maximum of 160');

if (errors.length > 0) {
    msg.rejection = { mode: 'train', reason: errors.join('; '), errors: errors };
    return [null, msg];
}
msg.validatedBy = 'node-red:validate-train';
return [msg, null];

// Node-RED function node: VALIDATE LOCATION DEMAND
//
// Demand events are structurally different from telemetry: there is no vehicle,
// no speed and no capacity. They describe how many people are waiting at a
// place, so this branch validates counts, a location type and a demand level.
//
// Outputs: 1 accepted | 2 rejected
var p = msg.payload;
var errors = [];

function isNonEmptyString(v) { return typeof v === 'string' && v.length > 0; }
function isInteger(v) { return typeof v === 'number' && isFinite(v) && Math.floor(v) === v; }

if (!isNonEmptyString(p.eventId)) errors.push('eventId is required');
if (!isNonEmptyString(p.locationId)) errors.push('locationId is required');
if (['busStop', 'tramStop', 'station'].indexOf(p.locationType) === -1) {
    errors.push("locationType must be one of busStop, tramStop, station (got '" + p.locationType + "')");
}
if (!Array.isArray(p.routeIds) || p.routeIds.length === 0) {
    errors.push('routeIds must be a non-empty array');
} else if (!p.routeIds.every(isNonEmptyString)) {
    errors.push('routeIds must contain non-empty strings');
}
if (!isNonEmptyString(p.timestamp) || isNaN(Date.parse(p.timestamp))) {
    errors.push('timestamp must be a valid ISO-8601 date');
}
if (!isInteger(p.passengerCount) || p.passengerCount < 0) errors.push('passengerCount must be >= 0');
if (['low', 'moderate', 'high', 'critical'].indexOf(p.demandLevel) === -1) {
    errors.push("demandLevel must be one of low, moderate, high, critical (got '" + p.demandLevel + "')");
}
if (p.waitingTimeSeconds !== undefined && (!isInteger(p.waitingTimeSeconds) || p.waitingTimeSeconds < 0)) {
    errors.push('waitingTimeSeconds must be >= 0 when present');
}

if (errors.length > 0) {
    msg.rejection = { mode: 'demand', reason: errors.join('; '), errors: errors };
    return [null, msg];
}
msg.validatedBy = 'node-red:validate-demand';
return [msg, null];

// Node-RED function node: NORMALISE
//
// What: converts an accepted, mode-specific raw event into the shared
//       normalised envelope, and sets the outbound MQTT topic.
// Why:  downstream services should not have to know four payload shapes. The
//       envelope gives them one uniform structure, while modeData preserves
//       every mode-specific field so no information is destroyed. This is the
//       last step before the event reaches the queue.
//
// Output topic: transport/normalized/{bus|tram|train|demand}
var p = msg.payload;
var mode = msg.transportMode;
var receivedAt = msg.receivedAt || new Date().toISOString();

var normalized = {
    schemaVersion: '1.0',
    eventId: p.eventId,
    sourceEventType: p.eventType,
    transportMode: mode,
    entityId: mode === 'demand' ? p.locationId : p.vehicleId,
    serviceId: p.serviceId === undefined ? null : p.serviceId,
    routeId: p.routeId === undefined ? null : p.routeId,
    routeIds: p.routeIds || (p.routeId ? [p.routeId] : []),
    locationId: p.locationId === undefined ? null : p.locationId,
    locationType: p.locationType === undefined ? null : p.locationType,
    timestamp: p.timestamp,
    receivedAt: receivedAt,
    position: null,
    metrics: {},
    health: 'normal',
    demandLevel: null,
    modeData: {},
    validation: { validatedBy: msg.validatedBy || 'node-red', branch: mode }
};

if (mode === 'demand') {
    normalized.metrics = {
        passengerCount: p.passengerCount === undefined ? null : p.passengerCount,
        waitingTimeSeconds: p.waitingTimeSeconds === undefined ? null : p.waitingTimeSeconds
    };
    normalized.demandLevel = p.demandLevel === undefined ? null : p.demandLevel;
    normalized.modeData = {
        locationType: p.locationType,
        shelterCapacity: p.shelterCapacity === undefined ? null : p.shelterCapacity
    };
} else {
    normalized.position = { latitude: p.latitude, longitude: p.longitude };
    normalized.metrics = {
        speedKph: p.speedKph === undefined ? null : p.speedKph,
        occupancy: p.occupancy === undefined ? null : p.occupancy,
        capacity: p.capacity === undefined ? null : p.capacity,
        delaySeconds: p.delaySeconds === undefined ? null : p.delaySeconds
    };
    normalized.health = p.health;
    // Copy so the mode-specific fields survive normalisation intact.
    normalized.modeData = Object.assign({}, p.modeData);
}

msg.payload = normalized;
msg.topic = 'transport/normalized/' + mode;

// Evidence-friendly one-liner. node.warn is used so it is visible in the
// Node-RED debug sidebar without needing a debug node wired to every branch.
var label = mode === 'demand'
    ? normalized.entityId + ' passengers=' + normalized.metrics.passengerCount
    : normalized.entityId + ' health=' + normalized.health + ' delay=' + normalized.metrics.delaySeconds + 's';
node.status({ fill: 'green', shape: 'dot', text: 'accepted ' + mode + ' ' + normalized.entityId });
node.warn('[ACCEPTED] mode=' + mode + ' eventId=' + normalized.eventId + ' ' + label);

return msg;

// Node-RED function node: REJECT
//
// What: formats a rejected event, publishes it to transport/rejected/<mode>
//       and logs a readable reason.
// Why:  invalid data must never reach the telemetry queue, and the rejection
//       must be explainable. The printed block is the evidence that the
//       validation branches are genuinely doing work.
var rejection = msg.rejection || { mode: 'unknown', reason: 'unspecified' };
var source = msg.payload || {};

var record = {
    rejectedAt: new Date().toISOString(),
    mode: rejection.mode,
    eventId: source.eventId || null,
    entityId: source.vehicleId || source.locationId || null,
    reason: rejection.reason,
    errors: rejection.errors || [rejection.reason],
    injectedFault: source.__injectedFault || null,
    rawTopic: msg.rawTopic || msg.topic || null
};

msg.payload = record;
msg.topic = 'transport/rejected/' + rejection.mode;

node.status({ fill: 'red', shape: 'ring', text: 'rejected ' + rejection.mode });
node.warn('[REJECTED]\n  mode=' + record.mode
    + '\n  eventId=' + record.eventId
    + '\n  reason=' + record.reason);

return msg;
